<?php
function team_inventory_filters(string $view,bool $dates=false): void { ?>
<form class="team-inventory-filters" data-team-filter="<?= escape($view) ?>" role="search"><div class="team-inventory-search"><?= stock_icon('search') ?><input type="search" name="q" maxlength="100" placeholder="<?= $view==='palets'?'Producto, EAN, palet o propietario':($view==='mercaderia'?'Producto, EAN o palet':'Palet, producto o persona') ?>" aria-label="Buscar en <?= escape($view) ?>"><details><summary class="library-secondary"><?= stock_icon('filter') ?><span>Filtros</span></summary><div class="team-inventory-options">
<?php if($dates): ?><label>Acción<select name="action"><option value="">Todas</option><?php $actions=$view==='administracion'?['invite_created'=>'Invitación creada','invite_revoked'=>'Invitación revocada','member_joined'=>'Acceso otorgado','member_role_changed'=>'Rango actualizado','member_revoked'=>'Acceso quitado','member_left'=>'Desvinculación','location_security_updated'=>'Configuración','company_assigned'=>'Empresa asignada','pallet_assigned'=>'Sucursal asignada']:['product_added'=>'Producto agregado','quantity_updated'=>'Cantidad modificada','quantity_deducted'=>'Mercadería retirada','product_removed'=>'Producto eliminado','expiry_updated'=>'Vencimiento modificado','reference_updated'=>'Nombre modificado','branch_updated'=>'Sucursal modificada','stock_transferred_in'=>'Mercadería recibida','stock_transferred_out'=>'Mercadería trasladada','ownership_transferred'=>'Propiedad transferida'];foreach($actions as $value=>$label): ?><option value="<?= escape($value) ?>"><?= escape($label) ?></option><?php endforeach; ?></select></label><label>Desde<input type="date" name="from" aria-label="Desde"></label><label>Hasta<input type="date" name="to" aria-label="Hasta"></label>
<?php else: ?><label>Vencimiento<select name="expiry"><option value="all">Todos</option><option value="expired">Vencidos</option><option value="upcoming">Por vencer</option><option value="none">Sin vencimiento</option></select></label><?php endif; ?>
</div></details></div><div class="team-filter-applied" data-applied></div><button type="button" class="team-text team-danger" data-clear hidden>Limpiar filtros</button></form><p class="team-hint" data-inventory-status="<?= escape($view) ?>" role="status"></p>
<?php }
